alter table public.email_campaigns add column if not exists campaign_type text not null default 'Email Marketing', add column if not exists campaign_type_color text not null default '#7c3aed';
alter table public.channel_campaigns add column if not exists campaign_type text not null default 'Zalo Marketing', add column if not exists campaign_type_color text not null default '#2563eb', add column if not exists combo_uv text, add column if not exists placement text, add column if not exists channel_rank text, add column if not exists owner_name text;
alter table public.email_campaigns add constraint email_campaigns_campaign_type_length check (btrim(campaign_type) <> '' and char_length(campaign_type) <= 100), add constraint email_campaigns_campaign_type_color_hex check (campaign_type_color ~ '^#[0-9A-Fa-f]{6}$');
alter table public.channel_campaigns add constraint channel_campaigns_campaign_type_length check (btrim(campaign_type) <> '' and char_length(campaign_type) <= 100), add constraint channel_campaigns_campaign_type_color_hex check (campaign_type_color ~ '^#[0-9A-Fa-f]{6}$'), add constraint channel_campaigns_marketing_metadata_length check ((combo_uv is null or char_length(combo_uv) <= 200) and (placement is null or char_length(placement) <= 200) and (channel_rank is null or char_length(channel_rank) <= 200) and (owner_name is null or char_length(owner_name) <= 200));
